package com.wandertrace.controller; import com.wandertrace.dto.*; import com.wandertrace.service.PublicMemoryService; import io.swagger.v3.oas.annotations.Operation; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/public/memories") public class PublicMemoryController{private final PublicMemoryService service;public PublicMemoryController(PublicMemoryService service){this.service=service;}@GetMapping("/{token}")@Operation(summary="Resolve a public NFC memory token") public ApiResponse<PublicMemoryResponse> get(@PathVariable String token){return ApiResponse.ok(service.find(token));}}
